@spec tracker_page_spec  src=tests/specs/tracker_page_spec.lua  loc=1994  cases=63
@exercises tuning (tuning), commandManager (h.cmgr), configManager (h.cm), midiManager (h.mm), trackerManager (h.tm)
@surface   tuning.derive, tuning.genDiamond, cmgr:scope, cmgr:installManifest, cm:setContext, cmgr:push, cmgr:invoke, cm:getAt, cm:set, cm:get, tuning.stepToMidi, mm:subscribe, mm:notes, tm:assignEvent, tm:byUuid, tm:flush
@harness   mk, reaper:addItem, reaper:setProjectTracks, reaper:seedMidi

# Intent
  Pin-tests for trackerPage's Page interface (bind / unbind / focusState /
  bind-from-cursor) and the retune modal's slots, defaults and dispatch.
  render / handleInput are stubs wired in step 3 and verified in REAPER, not here.

# Helpers
  @fn resetArrange()  @ 56-182
  @fn seedItems(h, takes, srcLen)  @ 198-203
      -- A bind re-keys cm's track tier off the take's own item, so a take named in
      -- fakeArrange needs one in the fake project too.
  @fn newTrackerPage(cm, ds, cmgr, chrome, gui, help)  @ 205-214
  @fn trackList(trackCount)  @ 216-222
  @fn mapBox(tv, take)  @ 225-229
      -- The box the map draws for a take: the travel consumes the window's own shapes.
  @fn mapTracker(harness, inst, trackCount)  @ 234-248
      -- A tracker bound to the take 'i0' over a track list of the given width, with
      -- i0's placement as the caller states it; inst = nil binds it into no instance.
      -- Returns the page's tv, the harness behind it for the cmgr, and the page itself.
  @fn chaseTracker(harness)  @ 252-277
      -- A tracker on track 0, bound to 'a0' in its first slot: 'b8' fills the second slot
      -- at QN 8, an audio item lies at 16, and 'c4' sits on the track beside it at 4.

# Cases
  @case 'the manifest declares every command the tracker page registers'  [harness]  @ 284-307
  @case 'every group the page places is one some scope declares'  [harness]  @ 313-328
  @case 'every bound command on the tracker page has a place on the cheat-sheet'  [harness]  @ 335-356
  @case 'bind(take) drives cm:setContext via the page's own tm:bindTake'  [harness]  @ 360-368
  @case 'unbind() drives cm:setContext(nil) via the page's own tm:bindTake'  [harness]  @ 371-380
  @case 'focusState before any render returns both bits false'  [harness]  @ 383-390
  @case 'bindFromSelection binds tm to the resolved selection take, drops when the track has no slots'  [harness]  @ 396-409
  @case 'with no live instance, the new take mints a parked slot and selects it'  [harness]  @ 413-430
  @case 'deleteBoundSlot confirms, then deletes the bound slot through the arrange facade'  [harness]  @ 436-457
  @case 'take properties renames the bound take\'s slot, not that one take'  [harness]  @ 463-481
  @case 'take properties follows the bound take when the tracker sits on another slot'  [harness]  @ 488-506
  @case 'the new take places below the current instance and becomes current'  [harness]  @ 512-545
  @case 'a new take on a just-selected track parks, rather than appending on the old one'  [harness]  @ 549-573
  @case 'duplicate below appends another instance of the bound slot and makes it current'  [harness]  @ 579-609
  @case 'duplicate below refuses where the free span falls short'  [harness]  @ 613-634
  @case 'duplicate below on a slot whose only take is parked does nothing'  [harness]  @ 638-651
  @case 'the variant step rebinds the tracker to the slot stepped to and follows its placement'  [harness]  @ 657-691
  @case 'a variant step with the tracker in no instance does nothing'  [harness]  @ 695-709
  @case 'prev/next track + take drive the tv selection, not the arrange cursor'  [harness]  @ 713-736
  @case 'a track step lands on the placement overlapping the current instance most'  [harness]  @ 740-776
  @case 'with nothing overlapping, a track step lands on the placement nearest in time'  [harness]  @ 780-815
  @case 'F6 plays from the instance dived into, not the placement the bind resolved'  [harness]  @ 822-839
  @case 'a dive outranks a play head already sitting in another instance'  [harness]  @ 843-866
  @case 'the play head entering an instance makes it current; leaving one writes nothing'  [harness]  @ 870-893
  @case 'with follow on, the play head carries the tracker across the bound track's slots'  [harness]  @ 899-914
  @case 'with follow off, the head entering another slot leaves the tracker where it was'  [harness]  @ 918-925
  @case 'the chase brackets no loop and raises no map tab'  [harness]  @ 929-944
  @case 'a slot change seeks from the outgoing instance, backwards for prevTake'  [harness]  @ 948-983
  @case 'the walk steps along the track's placements in start order, holding at the ends'  [harness]  @ 987-1035
  @case 'a walk into another slot resets the caret; within one slot the caret holds'  [harness]  @ 1039-1076
  @case 'deleting the instance drops that placement and lands on the one before it'  [harness]  @ 1080-1114
  @case 'a slot with no live instance leaves the tracker nowhere, and F6 silent'  [harness]  @ 1118-1134
  @case 'the map window centres the bound column, and clamps it at both ends'  [harness]  @ 1143-1161
  @case 'the map window pages time, a start in the last bar opening the next page'  [harness]  @ 1165-1181
  @case 'while following, the map window pages off the play head'  [harness]  @ 1185-1195
  @case 'with the tracker in no instance the map window pages on the edit cursor'  [harness]  @ 1199-1206
  @case 'the map window carries the takes over it, the current instance marked'  [harness]  @ 1210-1221
  @case 'the map window carries the transport it meets, and only that'  [harness]  @ 1225-1248
  @case 'the map loop candidate snaps to the cell, widens to one, and holds at 0'  [harness]  @ 1252-1271
  @case 'the map drives the transport, and a hand-set loop drops loop to item'  [harness]  @ 1275-1286
  @case 'a click on a map box travels to its instance, across tracks as well as slots'  [harness]  @ 1290-1329
  @case 'a map box that is no stop refuses the travel, as the walk passes it over'  [harness]  @ 1333-1347
  @case 'the pin key holds the map up as the palette default, and drops it when pressed again'  [harness]  @ 1351-1360
  @case 'a gesture raises the map, and it falls at the next command'  [harness]  @ 1364-1405
  @case 'the play row is the head\'s offset into the current instance, in rows'  [harness]  @ 1409-1436
  @case 'while following, the grid pages the scroll to hold the play row'  [harness]  @ 1440-1486
  @case 'the play row dims where the head is sounding a sibling instance'  [harness]  @ 1490-1514
  @case 'the cut row is where the rendered span stops short of the source'  [harness]  @ 1521-1542
  @case 'the play row and the head row count from the source origin, not the start'  [harness]  @ 1548-1572
  @case 'a dive carries the arrange QN to the caret row, and the caret hands it back'  [harness]  @ 1579-1598
  @case 'a caret outside the rendered span hands back the row the span stops at'  [harness]  @ 1602-1621
  @case 'leaving the tracker puts the arrange caret where the tracker caret is'  [harness]  @ 1625-1647
  @case 'with loop to item on, a dive brackets the instance dived into'  [harness]  @ 1653-1671
  @case 'the play head entering an instance leaves the loop where it was'  [harness]  @ 1675-1693
  @case 'the toggle command brackets the current instance as it comes on'  [harness]  @ 1697-1719
  @case 'Esc clears the loop and drops loop to item with it'  [harness]  @ 1723-1734
  @case 'the loop-to-item verb brackets the current instance, toggle or no toggle'  [harness]  @ 1738-1762
  @case 'retune opens on the scope the selection implies and OK snaps that scope'  [harness]  @ 1768-1823
  @case 'retune opens on the facility the take carries, its dials on their figures'  [harness]  @ 1831-1860
  @case 'a refused retune offers to widen, and the offer taken solves again'  [harness]  @ 1866-1909
  @case 'empty grid shows the single no-takes message'  [harness]  @ 1915-1929
  @case 'an owned tm flush resyncs the watcher baseline; only a foreign write trips the reload'  [harness]  @ 1936-1968
  @case 'bindFromSelection re-keys cm on return from dormancy even when the take is unchanged'  [harness]  @ 1972-1992

